<?php
if(!defined('ABSPATH'))exit;
function bsktv_schema(){if(!is_singular('post'))return;$id=get_the_ID();$d=array('@context'=>'https://schema.org','@type'=>'Article','headline'=>wp_strip_all_tags(get_the_title()),'url'=>get_permalink(),'datePublished'=>get_the_date('c'),'dateModified'=>get_the_modified_date('c'),'author'=>array('@type'=>'Person','name'=>get_the_author()));if(has_post_thumbnail())$d['image']=get_the_post_thumbnail_url($id,'full');$business=array('@type'=>'LocalBusiness','name'=>wp_strip_all_tags(get_the_title()));$address=bsktv_meta('bsktv_address');$phone=bsktv_meta('bsktv_phone');$hours=bsktv_meta('bsktv_hours');$url=bsktv_meta('bsktv_website');if($address)$business['address']=array('@type'=>'PostalAddress','streetAddress'=>$address);if($phone)$business['telephone']=$phone;if($hours)$business['openingHours']=$hours;if($url&&filter_var($url,FILTER_VALIDATE_URL))$business['url']=esc_url_raw($url);if(count($business)>2)$d['about']=$business;echo '<script type="application/ld+json">'.wp_json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).'</script>';}add_action('wp_head','bsktv_schema',20);
